import osos.chdir('/Users/akannan/Downloads/Lab/Proton-Computed-Tomography/')from pathlib import Pathimport ARW_Support_3.Manager_Class as man# Input Base Directory as well as location to Images folderBASE_DIR = Path('/Users/akannan/Downloads/Lab/Proton-Computed-Tomography/')IMAGES_FOLDER = BASE_DIR / "Images" / "ARW Files" / "Run11"#-------------------------------------------------------------------------##----THIS IS CODE USED FOR LOADING AND PROCESSING IMAGES FROM A FOLDER----##-------------------------------------------------------------------------#def get_image_names(folder: Path) -> list:    """    Returns sorted list of image filenames in a folder.    Sorts numerically if filenames contain numbers.    """    files = [f.name for f in folder.iterdir() if f.is_file()]    # Optional: filter only supported extensions    files = [f for f in files if f.lower().endswith(('.raw', '.arw'))]        # Sort numerically based on digits in filename    files = sorted(files, key=lambda x: int(''.join(filter(str.isdigit, x)) or 0))    return filesnames = get_image_names(IMAGES_FOLDER)print(f"Found {len(names)} images in {IMAGES_FOLDER}")Images = man.Manager()for name in names:    print(f"Processing: {name}")        title = Path(name).stem    filepath = IMAGES_FOLDER / name  # full path to the image file        try:        # Create Image object; open_bayer will auto-detect Sony vs Basler        img = Images.create_complete_image(name=title,                                            filename=str(filepath),                                            process=True,                                            mm_per_pixel = 0.00274)                '''img.crop_image(xstart=int(img.x_fit_params[1] - 5*img.x_fit_params[2]),                       xend=int(img.x_fit_params[1] + 5*img.x_fit_params[2]),                       ystart=int(img.y_fit_params[1] - 5*img.y_fit_params[2]),                       yend=int(img.y_fit_params[1] + 5*img.y_fit_params[2]))'''            except Exception as e:        print(f"[ERROR] {name}: {e}")        pass rejected = list(Images.review_images.keys())good = list(Images.images.keys())print(f"GOODS: {good}")print(f"REJECTS: {rejected}")for name, Image in Images.images.items():    print(name)    Image.plot_2d()    Image.plot_3d()    Image.plot_gaussian(axis=0, fit=True, show=True, title = f"{name} x")    Image.plot_gaussian(axis=1, fit=True, show=True, title = f"{name} y")#---------To check potenitally bad images, include this block-----------#'''for name, Image in Images.review_images.items():    print(name)    Image.plot_2d()'''#%%#-----------------------------------------------------## ---------- Input save location here ----------------##-----------------------------------------------------#Images.save_images("/Users/akannan/Downloads/Lab/ARW3TestRuns")#%%#----THIS IS CODE USED FOR RELOADING IMAGES FROM A FOLDER WHEN NEEDED----#'''Images = man.Manager()Images.load_images("/Users/akannan/Downloads/Lab/ARW3TestRuns")for name, Image in Images.images.items():    print(f"\nReloaded {name}")    Image.plot_gaussian(axis=0, fit=True, show=True, title = f"{name} x")    Image.plot_gaussian(axis=1, fit=True, show=True, title = f"{name} y")'''